import{_ as l,a0 as s,w as a,s as u,ao as i,I as r,x as e,a1 as p,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"使用Prey定位被盜的Ubuntu筆記本與智能電話 | LCTT x X-CMD","titleTemplate":false,"description":"使用Prey定位被盜的Ubuntu筆記本與智能電話 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用Prey定位被盜的Ubuntu筆記本與智能電話 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用Prey定位被盜的Ubuntu筆記本與智能電話 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150320 Locate Stolen laptops and Smart phones Using Prey Tool in Ubuntu","title":"使用Prey定位被盜的Ubuntu筆記本與智能電話","tag":"201505","desc":""},"relativePath":"201505/20150320 Locate Stolen laptops and Smart phones Using Prey Tool in Ubuntu.md","filePath":"[post].md"}'),d={name:"201505/20150320 Locate Stolen laptops and Smart phones Using Prey Tool in Ubuntu.md"};function P(y,t,g,m,b,T){const n=s("Link");return a(),u("div",null,[t[19]||(t[19]=i(`<h1 id="使用prey定位被盜的ubuntu筆記本與智能電話" tabindex="-1">使用Prey定位被盜的Ubuntu筆記本與智能電話 <a class="header-anchor" href="#使用prey定位被盜的ubuntu筆記本與智能電話" aria-label="Permalink to “使用Prey定位被盜的Ubuntu筆記本與智能電話”">​</a></h1><p>Prey是一款跨平台的開源工具，可以幫助你找回被盜的筆記本，台式機，平板和智能手機。它已經獲得了廣泛的流行，聲稱幫助找回了成百上千台丟失的筆記本和智能手機。Prey的使用特別簡單，首先安裝在你的筆記本或者手機上，當你的設備不見了，用你的賬號登入Prey網站，並且標記你的設備為“丟失”。只要小偷將設備接入網絡，Prey就會馬上發送設備的地理位置給你。如果你的筆記本有攝像頭，它還會拍下該死的賊。</p><p>Prey佔用很小的系統資源；你不會對你的設備運行有任何影響。你也可以配合其他你已經在設備上安裝的防盜軟件使用。Prey在你的設備與Prey服務器之間採用安全加密的通道進行數據傳輸。</p><h3 id="在ubuntu上安裝並配置prey" tabindex="-1">在Ubuntu上安裝並配置Prey <a class="header-anchor" href="#在ubuntu上安裝並配置prey" aria-label="Permalink to “在Ubuntu上安裝並配置Prey”">​</a></h3><p>讓我們來看看如何在Ubuntu上安裝和配置Prey，需要提醒的是，在配置過程中，我們必須到Prey官網進行賬號註冊。一旦完成上述工作，Prey將會開始監視你的設備了。免費的賬號最多可以監視三個設備，如果你需要添加更多的設備，你就需要購買合適的的套餐了。</p><p>可以想像Prey多麼流行與被廣泛使用，它現在已經被添加到了官方的軟件庫中了。這意味着你不要往軟件包管理器添加任何PPA。很簡單，登錄你的終端，運行以下的命令來安裝它：</p><pre><code>sudo apt-get install prey
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Install-Prey.png" alt="Install Prey"></p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Install-Prey-1.png" alt="Install Prey 1"></p><p>Prey是十分輕巧的軟件，只使用了系統幾兆的空間，安裝完成後，從Application &gt;&gt; Prey啓動，之後它會詢問你進行相關配置。</p><p>選擇“New User”，如果你是第一次使用的話。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-New-User.png" alt="Prey New User"></p><p>第二步實際上就是官網註冊的流程。請提供你的用户名，郵箱地址和密碼，來申清一個免費的賬號。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Register-Prey.png" alt="Register Prey"></p><p>點擊“Apply”完成，所有工作搞定，現在你的計算機被Prey保護了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Configuration.png" alt="Prey Configuration"></p>`,16)),r("p",null,[t[1]||(t[1]=e("登錄你最新建立的",-1)),p(n,{href:"https://preyproject.com/"},{default:o(()=>[...t[0]||(t[0]=[e("Prey 賬號",-1)])]),_:1}),t[2]||(t[2]=e("，你就應該可以在“Devices”菜單下看見你的設備信息了。",-1))]),t[20]||(t[20]=i('<p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Web-Login.png" alt="Prey Web Login"></p><p>只要你的筆記本或者任何其他設備丟失了，就登錄你的Prey網站賬號，然後點擊“Set Device to Missing”選項修改設備狀態為“missing”。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Missing-1.png" alt="Prey Missing Page"></p><p>從這裏選擇定時報告，並點擊“Yes，my device is missing”。定時報告選項是指一段時間間隔後，軟件會更新併發送給你設備的地理位置。它還會從網頁界面那發郵件給你，只要設備的狀態改變了。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Missing-2.png" alt="Prey Missing Email"></p><p>而一旦被盜的設備接入了互聯網，Prey就會馬上發送報告給你，包括設備的地理位置和IP地址。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Missing-3.png" alt="Prey Found Report"></p><p>點擊報告鏈接，你應該會看到設備的地理位置和IP地址。</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Prey-Final.png" alt="Prey Final"></p><p>Prey有一個明顯的不足。它需要你的設備接入互聯網才會發送地理位置給你，如果小偷比較聰明，在接入網絡前將你的設備磁盤格式化了，那麼你就永遠不會收到設備被發現的報告了。但是這裏仍然是有一個方法克服這個不足，確保添加一個BIOS密碼，並且禁用從可移除的設備裏啓動系統。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3>',11)),r("p",null,[t[4]||(t[4]=e("這是一款小巧，非常有用的安全保護應用，可以讓你在一個地方追蹤你所有的設備，儘管不完美，但是仍然提供了找回被盜設備的機會。它在Linux，Windows和Mac平台上無縫運行。以上就是",-1)),p(n,{href:"https://preyproject.com/plans"},{default:o(()=>[...t[3]||(t[3]=[e("Prey",-1)])]),_:1}),t[5]||(t[5]=e("完整使用的所有細節。",-1))]),t[21]||(t[21]=r("hr",null,null,-1)),r("p",null,[t[7]||(t[7]=e("via: ",-1)),p(n,{href:"http://linoxide.com/ubuntu-how-to/anti-theft-application-prey-ubuntu/"},{default:o(()=>[...t[6]||(t[6]=[e("http://linoxide.com/ubuntu-how-to/anti-theft-application-prey-ubuntu/",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=e("作者：",-1)),p(n,{href:"http://linoxide.com/author/arunrz/"},{default:o(()=>[...t[8]||(t[8]=[e("Aun Raza",-1)])]),_:1}),t[12]||(t[12]=e(" 譯者：",-1)),p(n,{href:"https://github.com/wi-cuckoo"},{default:o(()=>[...t[9]||(t[9]=[e("wi-cuckoo",-1)])]),_:1}),t[13]||(t[13]=e(" 校對：",-1)),p(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[16]||(t[16]=e("本文由 ",-1)),p(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原創翻譯，",-1)),p(n,{href:"http://linux.cn/"},{default:o(()=>[...t[15]||(t[15]=[e("Linux中國",-1)])]),_:1}),t[18]||(t[18]=e(" 榮譽推出",-1))])])}const U=l(d,[["render",P]]);export{w as __pageData,U as default};
